"""Source evidence for the raw scan byte and its verified renderer caller."""
import sys,json
from pathlib import Path
sys.dont_write_bytecode=True
p=Path(__file__).resolve().parents[2];sys.path.insert(0,str(p/'skoolkit-10.1'))
from skoolkit.traceutils import disassemble
from skoolkit.z80 import Assembler
m=bytes(0x5d80)+(p/'sherlock-analisi/block-10.bin').read_bytes();asm=Assembler()
regions=[(0xA3D6,0xA3E2,'code','Nome del primo argomento: profondità del prefisso qualificato'),(0xA9DF,0xAA10,'code','Scarico della parola: ritorno a capo prima dei glifi'),(0xC363,0xC37D,'code','Pulizia della riga: spazio e chiamata al renderer'),(0xC388,0xC3E4,'code','Glifo: riga del font conservata accanto ai flag nello stack')]
notes={0xA3DE:'Nel chiamante verificato CLIMB INTO/TAKE OFF, il prefisso qualificato passa da A745/A751 a D3E8; durante il suo scarico C388 ha frame5D2C. Non estendere questo contratto a tutti i nomi o a richieste isolate.',0xA9DF:'Il buffer contiene una parola intera. Salvataggi e chiamate contribuiscono alla profondità dello stack, oltre alla sola stampa del glifo.',0xA9EB:'Se la parola non entra, il CR precede lo scarico. Nel prefisso con frame5D2C la pulizia arriva a C388 con frame5D26.',0xA9F1:'AA14 con CR provoca scroll e pulizia prima di riprendere i caratteri della parola. Il byte 5D1B deriva quindi da uno spazio, non da una lettera di hansom.',0xA9F5:'B riceve la lunghezza della parola; con un altro frame lo stesso byte fisico può conservare un conteggio, non una scansione del font.',0xC363:'Prepara il riempimento della riga inferiore dopo lo scroll. Il numero di colonne dipende dal canale.',0xC372:'Lo spazio viene ottenuto dal font vero, non da un valore registrato. La sua ottava riga è zero, ma altri glifi, per esempio q, hanno righe nonzero.',0xC374:'Con frame C388=5D26 i salvataggi AF interni scrivono F a5D1A e A a5D1B. Nel percorso naturale il writer pertinente è C3B8 a tick962, Lestrade che sale sul cab.',0xC388:'Salva AF del chiamante. Il frame è parte del contratto: la stessa cella può conservare informazioni diverse con altre profondità.',0xC39C:'B/C dell’ultima scansione sono1/shift: con frame5D24, 5D1B corrisponde a B=1, non alla riga del font. Le prove controllate distinguono i due casi.',0xC39D:'Primo PUSH AF della scansione; A è il byte del font non allineato. Con shift zero non serve il secondo PUSH, e questo rimane il writer.',0xC3B3:'Il ciclo di shift modifica A soltanto per disegnare; POP AF ripristina il byte non allineato prima del salvataggio successivo.',0xC3B8:'PUSH AF salva di nuovo la riga del font non allineata. All’ottavo passaggio, con frame5D26, A=glyph[7] occupa5D1B. Non confondere A con F a5D1A né sostituire entrambi con zero.',0xC3D2:'Il ciclo esegue otto scansioni: il residuo è l’ultima riga del glifo. Le prove coprono ogni colonna, inclusi gli shift zero.',0xC3E2:'Ripristina AF del chiamante al ritorno; il contenuto residuo dello stack rimane finché un altro writer non lo sovrascrive.'}
fields={0xC388:[['5D1B','A dello scan, solo chiamante verificato','Frame5D26: ottava riga non allineata del font. Frame5D24: la stessa cella conserva B=1. Non derivare il valore da F'],['Proprietà','condizionata al chiamante','Prefisso qualificato CLIMB INTO/TAKE OFF; gli altri output revocano. Gli ordini GO TO del prefisso già verificato preservano la coppia se non la raggiungono'],['5D1C–5D1E','nessun nuovo valore introdotto','Restano fuori da questo contratto: nessun completamento dai byte vicini o dal payload iniziale']]}
lines=['; Analisi offline con riassellaggio del payload; nessuna CPU nel motore JS.'];count=total=0
for a,b,kind,label in regions:
 lines+=['',f'    ORG ${a:04X}',f'; {kind.upper()}: {label}'];at=a
 while at<b:
  op,n=disassemble(m,at);assert at+n<=b,(hex(at),op);assert bytes(asm.assemble(op,at))==m[at:at+n]
  lines.append(f'    {op:<37} ; ${at:04X} {m[at:at+n].hex(" ")}'+(' | '+notes[at]if at in notes else''));at+=n;total+=n;count+=1
root=p/'sherlock-js/results/glyph-byte';root.mkdir(exist_ok=True)
(root/'glyph-byte.asm').write_text('\n'.join(lines)+'\n')
(root/'listing-verification.json').write_text(json.dumps(dict(roundtrip_equal=True,instructions=count,bytes_roundtripped=total,regions=[dict(start=f'{a:04X}',end_exclusive=f'{b:04X}',kind=k,label=l,atlas_priority=95,**({'fields':fields[a]}if a in fields else{}))for a,b,k,l in regions]),indent=2)+'\n');print(count,total)
